let rec filter (f : 'a -> bool) (s : 'a stream) : 'a stream =
  let h = s.head in 
  let res = fun () -> filter f (force s.tail) in
  if f h then
    {
      head = h; 
      tail = Susp res 
    }
  else
    let res = res () in
    {
      head = res.head; 
