(* factorial *)
let factorial (n: int) : int =
  if (n = 0) then 1 else
    let rec factorial' (i: int) (acc: int) : int =
      if (i = n) then acc * n
      else factorial' (i + 1) (acc * i)
    in 
    factorial' 1 1
;;
(* Binomial (n choose k) := n! / (k! (n - k)!) *) 
let binomial n k =
  (factorial n) / ((factorial k) * (factorial (n - k)))
;;



